{
  "name": "@sulesky/opencode-plugger-tui",
  "version": "0.1.4",
  "description": "TUI module for @sulesky/opencode-plugger — register in `tui.json` `plugin[]`.",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "opencode-tui-plugin",
    "claude-code"
  ],
  "homepage": "https://github.com/kapelan/plugger-open-code#readme",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/kapelan/plugger-open-code.git"
  },
  "bugs": {
    "url": "https://github.com/kapelan/plugger-open-code/issues"
  },
  "author": "Lucjan Sulewski",
  "type": "module",
  "main": "./dist-tui/index.js",
  "$comment_exports": "OpenCode's plugin loader (`packages/opencode/src/plugin/shared.ts:resolvePackageEntrypoint`) resolves a TUI plugin by reading `exports['./tui']` exclusively — kind='tui' does NOT fall back to `main`. Without this key the npm-installed package errors with 'does not expose a tui entrypoint'.",
  "exports": {
    ".": {
      "default": "./dist-tui/index.js"
    },
    "./tui": {
      "default": "./dist-tui/index.js"
    },
    "./package.json": "./package.json"
  },
  "files": [
    "dist-tui",
    "README.md"
  ],
  "publishConfig": {
    "access": "public"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.14"
  },
  "dependencies": {
    "@sulesky/opencode-plugger": "0.1.4"
  },
  "license": "MIT"
}
